python - <<'PY'
import numpy as np
from PIL import Image
from scipy import ndimage as ndi
for f in ['/app/target.png','/app/output/inspect_practice_cam.png']:
 im=np.array(Image.open(f).convert('RGB')); gray=im.mean(2)
 print(f,im.shape,gray.min(),gray.max())
 if 'practice' in f:
  m=gray<60; lab,n=ndi.label(m)
  obj=ndi.find_objects(lab)
  print(sorted([(int((lab[s]==i+1).sum()),s) for i,s in enumerate(obj) if s], key=lambda x:x[1][0].start if isinstance(x[1],tuple) else 0))
  for s in obj:
   if s:
    sl=lab[s]; a=int((sl>0).sum());
    if a>100: print('bbox',s,'area',a)
 else:
  m=gray<100; lab,n=ndi.label(m); print('n',n)
  ys,xs=np.where(m);print('bounds',xs.min(),ys.min(),xs.max(),ys.max(),'area',int(m.sum()))
  for i,s in enumerate(ndi.find_objects(lab)):
   if s:
    a=int((lab[s]==i+1).sum())
    if a>100: print('bbox',s,'area',a)
